// Banco de preguntas tipo examen del módulo «diagnostico» (CCST Networking, dominio 5). Clave = nivel de práctica.
import { op, vs, rel, ord } from './_ayuda.mjs';

const PING_OK = `C:\\> ping 192.168.1.1

Respuesta desde 192.168.1.1: bytes=32 tiempo=1ms TTL=64
Respuesta desde 192.168.1.1: bytes=32 tiempo=1ms TTL=64

C:\\> ping 8.8.8.8

Respuesta desde 8.8.8.8: bytes=32 tiempo=15ms TTL=117
Respuesta desde 8.8.8.8: bytes=32 tiempo=14ms TTL=117

C:\\> ping www.example.com
La solicitud de ping no pudo encontrar el host www.example.com.`;

